mapper.select:
SELECT t.id, t.instance_id, t.node_name, t.assignee, t.status, t.create_time, t.complete_time, i.title, i.start_user FROM approval_task t INNER JOIN approval_instance i ON i.id = t.instance_id WHERE t.assignee = #{userId}
AND t.status IN ('APPROVED', 'REJECTED', 'CANCELLED') AND t.status = 'PENDING' AND i.status = 'PENDING' AND i.current_node_id = t.node_id
AND i.title LIKE CONCAT('%', #{query.title}, '%') ORDER BY t.create_time DESC, t.id DESC
